-- Criação das tabelas
CREATE TABLE acoes (IDAcao TEXT PRIMARY KEY, Pilar TEXT, NomeAcao TEXT, Atividade TEXT, MetaFinep TEXT, RubricaOrcamentaria TEXT, ValorEstimado TEXT);
CREATE TABLE atividades (IDAtividade TEXT PRIMARY KEY, Acoes TEXT, Ordem TEXT, Atividade TEXT, Descricao TEXT, IndicadorFisico TEXT, DataInicio TEXT, DataFim TEXT, Responsavel TEXT, Status TEXT, Observacao TEXT, LinkEvidencia TEXT);
CREATE TABLE subatividades (IDSubatividade TEXT PRIMARY KEY, IDAtividade TEXT, OrdemSub TEXT, Subatividade TEXT, Descricao TEXT, DataInicio TEXT, DataFim TEXT, Responsavel TEXT, Status TEXT, Observacao TEXT, LinkEvidencia TEXT, IndicadorFisico TEXT);

